/*
 * The Faith Received — memorize mode.
 *
 * Ported from cvs4bz49sb-oss/heidelberg/components/MemoryMode.tsx.
 * One Q&A at a time, hidden answer, reveal-on-click, mark-as-
 * memorized + filter, persistent localStorage progress, keyboard
 * shortcuts. Pure client-side; all state lives in localStorage
 * keyed per-document.
 *
 * Markup contract (per-doc, generated by build-faith-received.mjs):
 *   <main data-faith-memorize data-doc-slug data-doc-title>
 *   <script type="application/json" data-faith-memorize-data>[{...}]</script>
 *
 * Each entry: { number, question, answer, references[], lordsDay?, lordsDayTitle? }
 */
(function () {
  "use strict";
  var root = document.querySelector("[data-faith-memorize]");
  if (!root) return;

  var slug = root.getAttribute("data-doc-slug") || "";
  var STORAGE_KEY = "faith-memorize:" + slug;

  // Load Q&A data from inline JSON.
  var dataNode = document.querySelector("[data-faith-memorize-data]");
  var questions = [];
  try { questions = JSON.parse(dataNode.textContent || "[]"); } catch (_) { return; }
  if (!questions.length) return;

  // Persistent state.
  var state = loadState();
  var memorized = new Set(state.memorized || []);
  var filter = "all";
  var index = 0;
  var revealed = false;

  function loadState() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      return raw ? JSON.parse(raw) : { memorized: [], lastIndex: 0 };
    } catch (_) {
      return { memorized: [], lastIndex: 0 };
    }
  }
  function saveState() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({
        memorized: Array.from(memorized),
        lastIndex: index,
      }));
    } catch (_) {}
  }

  function filtered() {
    if (filter === "memorized") return questions.filter(function (q) { return memorized.has(q.number); });
    if (filter === "unmemorized") return questions.filter(function (q) { return !memorized.has(q.number); });
    return questions;
  }

  // DOM refs
  var els = {
    question: root.querySelector("[data-faith-memorize-question]"),
    numeral: root.querySelector("[data-faith-memorize-numeral]"),
    answer: root.querySelector("[data-faith-memorize-answer]"),
    answerText: root.querySelector("[data-faith-memorize-answer-text]"),
    refs: root.querySelector("[data-faith-memorize-refs]"),
    reveal: root.querySelector("[data-faith-memorize-reveal]"),
    mark: root.querySelector("[data-faith-memorize-mark]"),
    prev: root.querySelector("[data-faith-memorize-prev]"),
    next: root.querySelector("[data-faith-memorize-next]"),
    progressLabel: root.querySelector("[data-faith-memorize-progress-label]"),
    progressPct: root.querySelector("[data-faith-memorize-progress-pct]"),
    progressFill: root.querySelector("[data-faith-memorize-progress-fill]"),
    position: root.querySelector("[data-faith-memorize-position]"),
    total: root.querySelector("[data-faith-memorize-total]"),
    card: root.querySelector("[data-faith-memorize-card]"),
    empty: root.querySelector("[data-faith-memorize-empty]"),
    filters: root.querySelectorAll("[data-faith-memorize-filter]"),
  };

  function escapeHtml(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  function smarten(text) {
    if (!text) return "";
    var s = String(text);
    s = s.replace(/(^|[\s\(\[\{])'/g, "$1‘").replace(/'/g, "’");
    s = s.replace(/(^|[\s\(\[\{])"/g, "$1“").replace(/"/g, "”");
    return s;
  }

  function paragraphsHtml(text) {
    return String(text || "")
      .split(/\n\s*\n/)
      .map(function (p) { return p.trim(); })
      .filter(Boolean)
      .map(function (p) { return "<p>" + escapeHtml(smarten(p)) + "</p>"; })
      .join("");
  }

  function render() {
    var list = filtered();
    if (!list.length) {
      els.card.hidden = true;
      els.empty.hidden = false;
      updateProgress();
      return;
    }
    els.card.hidden = false;
    els.empty.hidden = true;
    if (index >= list.length) index = 0;
    if (index < 0) index = list.length - 1;

    var q = list[index];
    var numeralPrefix = q.lordsDay ? ("Lord's Day " + q.lordsDay + " &middot; Q. " + q.number) : ("Q. " + q.number);
    els.numeral.innerHTML = numeralPrefix;
    els.question.innerHTML = "<em>" + escapeHtml(smarten(q.question)) + "</em>";
    els.answerText.innerHTML = paragraphsHtml(q.answer);
    if (q.references && q.references.length) {
      var refsHtml = q.references.map(function (r) {
        return '<button type="button" class="faith-verse-ref" data-faith-verse data-book="' + escapeHtml(r.book || "") + '" data-reference="' + escapeHtml(r.reference || r.book || "") + '">' + escapeHtml(r.reference || r.book || "") + "</button>";
      }).join('<span class="faith-verse-sep" aria-hidden="true"> &middot; </span>');
      els.refs.innerHTML = '<span class="faith-qa-ref-label">Scripture</span> ' + refsHtml;
      els.refs.hidden = false;
    } else {
      els.refs.hidden = true;
    }
    els.answer.hidden = !revealed;
    els.reveal.textContent = revealed ? "Hide answer" : "Reveal answer";
    var isMem = memorized.has(q.number);
    els.mark.textContent = isMem ? "Mark not yet" : "Mark memorized";
    els.mark.classList.toggle("is-memorized", isMem);
    els.position.textContent = String(index + 1);
    els.total.textContent = String(list.length);
    updateProgress();
  }

  function updateProgress() {
    var total = questions.length;
    var n = memorized.size;
    var pct = total ? Math.round((n / total) * 100) : 0;
    els.progressLabel.textContent = n + " of " + total + " memorized";
    els.progressPct.textContent = pct + "%";
    els.progressFill.style.width = pct + "%";
  }

  // Wire up
  els.reveal.addEventListener("click", function () {
    revealed = !revealed;
    render();
  });
  els.mark.addEventListener("click", function () {
    var list = filtered();
    if (!list.length) return;
    var q = list[index];
    if (memorized.has(q.number)) memorized.delete(q.number);
    else memorized.add(q.number);
    saveState();
    render();
  });
  els.prev.addEventListener("click", function () {
    revealed = false;
    index--;
    saveState();
    render();
  });
  els.next.addEventListener("click", function () {
    revealed = false;
    index++;
    saveState();
    render();
  });
  Array.prototype.forEach.call(els.filters, function (btn) {
    btn.addEventListener("click", function () {
      filter = btn.getAttribute("data-faith-memorize-filter") || "all";
      Array.prototype.forEach.call(els.filters, function (b) {
        b.classList.remove("is-active");
        b.setAttribute("aria-selected", "false");
      });
      btn.classList.add("is-active");
      btn.setAttribute("aria-selected", "true");
      index = 0;
      revealed = false;
      render();
    });
  });

  // Keyboard
  document.addEventListener("keydown", function (e) {
    if (e.target && /^(INPUT|TEXTAREA)$/.test(e.target.tagName)) return;
    if (e.key === "ArrowRight" || e.key === "ArrowDown") {
      e.preventDefault();
      revealed = false;
      index++;
      saveState();
      render();
    } else if (e.key === "ArrowLeft" || e.key === "ArrowUp") {
      e.preventDefault();
      revealed = false;
      index--;
      saveState();
      render();
    } else if (e.key === " " || e.key === "Enter") {
      e.preventDefault();
      revealed = !revealed;
      render();
    } else if (e.key === "m" || e.key === "M") {
      els.mark.click();
    }
  });

  // Restore last position (clamped to filtered list).
  var startIdx = Math.max(0, Math.min((state.lastIndex || 0), filtered().length - 1));
  index = startIdx;
  render();
})();
